{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C46"],
      "claim": "Isotretinoin, the closest retinoid acid analog, has a systemic bioavailability of 40% at 1 mg/kg/day, supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "Acitretin, a retinoid acid, has an absolute oral bioavailability of approximately 60% (range 36–95%), supporting high retinoid bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Etretinate, a neutral lipophilic retinoid ester, has an absolute oral bioavailability of about 40%, indicating that non-ionizable lipophilic retinoids can exceed the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "All-trans retinoic acid oral bioavailability was estimated at 25–30%, still above the 20% threshold.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Fenretinide is a retinoid amide; structurally related retinoids (isotretinoin 40%, acitretin ~60%, etretinate ~40%, ATRA 25–30%) consistently show oral bioavailability above 20%, supporting a high F ≥ 20% prediction despite qualitative reports of variable absorption.",
  "evidence_gaps": [
    "Direct absolute oral bioavailability data for fenretinide (the query amide) are absent; all evidence is from retinoid acids/esters and unrelated drugs.",
    "Qualitative 'low' bioavailability reports for 13-cis-retinoic acid/ATRA are not quantified relative to the 20% threshold.",
    "Formulation and fed-state effects on the query amide are unknown."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

